/// <summary>
/// SalesOrderLineCDSV2Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesOrderLineCDSV2Entity))]
final class METSalesOrderLineCDSV2Entity_Extension
{
    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        SalesLine                       metSalesLineStd;
        SalesTable                      metSalesTableStd;        
        InventDim                       metInventDimStd;
        METSalesOrderCDSEntityHelper    metSalesOrderCDSEntityHelper   = new METSalesOrderCDSEntityHelper();
        boolean                         metModified;
        boolean                         metCancelSalesLine;

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity) &&
            _entityCtx.isDatabaseOperationInsert())
        {
            SalesOrderLineV2Entity  metSalesorderLineEntityStd   = _dataSourceCtx.getBuffer();
            metSalesTableStd  = SalesTable::find(metSalesorderLineEntityStd.SalesOrderNumber);

            metInventDimStd.InventSiteId        = metSalesorderLineEntityStd.ShippingSiteId;
            metInventDimStd.InventLocationId    = metSalesorderLineEntityStd.ShippingWarehouseId;
            metInventDimStd   = InventDim::findOrCreate(metInventDimStd);

            UnitOfMeasureSymbol     metInventUnit  = InventTable::find(metSalesorderLineEntityStd.ItemNumber).inventUnitId();
            InventQty               metOrderedQty  = metSalesOrderCDSEntityHelper.calculateInventoryQty(metSalesorderLineEntityStd,
                                                                                                     metInventDimStd.inventDimId,
                                                                                                     metInventUnit);
            
            metModified = metSalesOrderCDSEntityHelper.substituteItem(metSalesorderLineEntityStd, 
                                                                      metInventDimStd, 
                                                                      metOrderedQty);

            if (metModified)
            {
                metInventUnit  = InventTable::find(metSalesorderLineEntityStd.ItemNumber).inventUnitId();
                metOrderedQty  = metSalesOrderCDSEntityHelper.calculateInventoryQty(metSalesorderLineEntityStd,
                                                                                    metInventDimStd.inventDimId,
                                                                                    metInventUnit);
            }
             

            if (metSalesOrderCDSEntityHelper.checkOrderGuides(metSalesorderLineEntityStd, metSalesTableStd.CustAccount))
            {
                if (metSalesOrderCDSEntityHelper.applyPalletRounding(metSalesorderLineEntityStd,
                                                                     metInventDimStd, 
                                                                     metInventUnit, 
                                                                     metOrderedQty))
                {
                    metModified     = true;

                    metOrderedQty  = metSalesOrderCDSEntityHelper.calculateInventoryQty(metSalesorderLineEntityStd,
                                                                                        metInventDimStd.inventDimId,
                                                                                        metInventUnit);
                }

                if (metSalesTableStd.Reservation == ItemReservation::Automatic && 
                    metSalesOrderCDSEntityHelper.onHandInventory(metSalesorderLineEntityStd.ItemNumber, metInventDimStd) < metOrderedQty)
                {
                    if (metSalesOrderCDSEntityHelper.substituteItem(metSalesorderLineEntityStd, 
                                                                    metInventDimStd, 
                                                                    metOrderedQty, 
                                                                    true,
                                                                    false))
                        
                    {
                        metModified     = true;

                        if (metSalesOrderCDSEntityHelper.checkOrderGuides(metSalesorderLineEntityStd, metSalesTableStd.CustAccount))
                        {
                            metSalesOrderCDSEntityHelper.applyPalletRounding(metSalesorderLineEntityStd,
                                                                             metInventDimStd,
                                                                             metInventUnit,
                                                                             metOrderedQty);
                        }
                        else
                        {
                            metCancelSalesLine  = true;
                        }
                    }
                }
            }
            else
            {
                metModified         = true;
                metCancelSalesLine  = true;
            }

            if (metModified)
            {
                metSalesorderLineEntityStd.METOrderExtractStatus    = METOrderExtractStatus::None;
            }

            _dataSourceCtx.setBuffer(metSalesorderLineEntityStd);
        }

        boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx); 

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity))
        {
            
            SalesOrderLineV2Entity  metSalesorderLineEntityStd  = _dataSourceCtx.getBuffer();
            METSalesLine            metSalesLineUpdate;

            select firstonly metSalesLineStd
                where metSalesLineStd.InventTransId == metSalesorderLineEntityStd.InventoryLotId
                outer join METSalesLineUpdate
                    where METSalesLineUpdate.SalesLine  == metSalesLineStd.RecId;

            if(metCancelSalesLine || ReasonTable::find(metSalesLineUpdate.ReasonId).METCancelLineOnCreation)
            {
                ttsbegin;
                metSalesLineStd.selectForUpdate(true);
                SalesUpdateRemain::construct().updateDeliverRemainder(metSalesLineStd, 0, 0);
                ttscommit;
            }

            if(metModified && metSalesLineUpdate.RecId)
            {
                ttsbegin;

                metSalesLineUpdate.selectForUpdate(true);
                metSalesLineUpdate.OrderExtractStatus   = METOrderExtractStatus::Open;
                metSalesLineUpdate.update();

                ttscommit;                
            }                   
        }
    
        return ret;
    }

    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        next postLoad();

        this.METReservedQuantity = SalesLine::findInventTransId(this.InventoryLotId).reservedPhysical();

    }
